121	/**
122	 * ユーザーの表示名を更新
123	 */
124	export async function updateUserDisplayName(userId: string, displayName: string) {
125	    const supabase = await createSupabaseAdminClient();
126	    
127	    const { error } = await supabase
128	        .schema('member')
129	        .from('members')
130	        .update({ display_name: displayName })
131	        .eq('supabase_auth_user_id', userId);
132	    
133	    return { success: !error, error };
134	}
