136	/**
137	 * 全ユーザーの表示名を一括更新
138	 */
139	export async function updateAllUserDisplayNames() {
140	    const supabase = await createSupabaseAdminClient();
141	
142	    try {
143	        const { data: members, error: fetchError } = await supabase
144	            .schema('member')
145	            .from('members')
146	            .select('supabase_auth_user_id, discord_uid');
147	
148	        if (fetchError || !members) {
149	            return { success: false, message: 'ユーザーの取得に失敗しました。' };
150	        }
151	
152	        let successCount = 0;
153	        let failCount = 0;
154	
155	        // 並列処理で全ユーザーの名前を更新（エラー耐性）
156	        await Promise.allSettled(
157	            members.map(async (member: any) => {
158	                if (!member.discord_uid) return;
159	
160	                try {
161	                    const { data: nickname, error } = await fetchMemberNickname(member.discord_uid);
162	                    
163	                    if (nickname && !error) {
164	                        const { error: updateError } = await supabase
165	                            .schema('member')
166	                            .from('members')
167	                            .update({ display_name: nickname })
168	                            .eq('supabase_auth_user_id', member.supabase_auth_user_id);
169	
170	                        if (!updateError) {
171	                            successCount++;
172	                        } else {
173	                            failCount++;
174	                        }
175	                    } else {
176	                        failCount++;
177	                    }
178	                } catch {
179	                    failCount++;
180	                }
181	            })
182	        );
183	
184	        return {
185	            success: true,
186	            message: `更新完了: 成功 ${successCount}件、失敗 ${failCount}件`,
187	        };
188	    } catch (error) {
189	        console.error('Error updating all display names:', error);
190	        return { success: false, message: '更新中にエラーが発生しました。' };
191	    }
192	}
193	
194	/**
195	 * ユーザーのカードIDを更新
196	 */
197	export async function updateUserCardId(userId: string, newCardId: string) {
198	    const supabase = await createSupabaseAdminClient();
199	
200	    try {
201	        // カードIDを正規化（コロンを削除、小文字化）
202	        const normalizedCardId = newCardId.toLowerCase().replace(/:/g, '');
203	
204	        // 既存のカードIDとの重複チェック
205	        const { data: existingUser, error: checkError } = await supabase
206	            .schema('attendance')
207	            .from('users')
208	            .select('supabase_auth_user_id')
209	            .eq('card_id', normalizedCardId)
210	            .neq('supabase_auth_user_id', userId)
211	            .single();
212	
213	        if (existingUser) {
214	            return { success: false, message: 'このカードIDは既に使用されています。' };
215	        }
216	
217	        // カードIDを更新
218	        const { error: updateError } = await supabase
219	            .schema('attendance')
220	            .from('users')
221	            .update({ card_id: normalizedCardId })
222	            .eq('supabase_auth_user_id', userId);
223	
224	        if (updateError) {
225	            console.error('Error updating card ID:', updateError);
226	            return { success: false, message: 'カードIDの更新に失敗しました。' };
227	        }
228	
229	        return { success: true, message: 'カードIDを更新しました。' };
230	    } catch (error) {
231	        console.error('Error in updateUserCardId:', error);
232	        return { success: false, message: '予期しないエラーが発生しました。' };
233	    }
234	}
